const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const params = {
    query: item.json.search_query || item.json.query || "",
    alpha: item.json.alpha !== undefined ? parseFloat(item.json.alpha) : 0.5,
    limit: item.json.limit !== undefined ? parseInt(item.json.limit) : 10,
    min_score: item.json.min_score !== undefined ? parseFloat(item.json.min_score) : 0.2,
    min_quality: item.json.min_quality !== undefined ? parseFloat(item.json.min_quality) : 0.2
  };

  if (!params.query || params.query.trim() === "") {
    throw new Error("Query parameter is required and cannot be empty");
  }

  if (params.alpha < 0 || params.alpha > 1) {
    throw new Error("Alpha must be between 0.0 and 1.0");
  }

  if (params.limit < 1 || params.limit > 50) {
    throw new Error("Limit must be between 1 and 50");
  }

  if (params.min_score < 0 || params.min_score > 1) {
    throw new Error("min_score must be between 0.0 and 1.0");
  }

  if (params.min_quality < 0 || params.min_quality > 1) {
    throw new Error("min_quality must be between 0.0 and 1.0");
  }

  outputs.push({ json: params });
}

return outputs;

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const response = item.json;

  if (!response.results || response.results.length === 0) {
    outputs.push({
      json: {
        success: true,
        message: "No results found. Try broader search terms.",
        query: response.query || "",
        results_count: 0,
        results: []
      }
    });
    continue;
  }

  const formattedResults = response.results.map((result, index) => {
    return {
      rank: index + 1,
      document_code: result.document_id || "Unknown",
      title: result.document_name || "Untitled Document",
      department: result.department || "Unknown",
      content_snippet: result.content ? result.content.substring(0, 300) + "..." : "",
      relevance_score: result.score ? result.score.toFixed(3) : "N/A",
      version: result.version || "N/A",
      citation: `**${result.document_id || "Unknown"}** (${result.document_name || "Untitled"}${result.version ? ", " + result.version : ""})`
    };
  });

  const formattedResponse = {
    success: true,
    search_type: "hybrid",
    query: response.query || "",
    results_count: formattedResults.length,
    results: formattedResults,
    summary: `Found ${formattedResults.length} documents for "${response.query || ""}"\n\nTop result: ${formattedResults[0].citation}`
  };

  outputs.push({ json: formattedResponse });
}

return outputs;
